class ChartBoundary extends Component<{children: ReactNode}, {error: boolean}> {state={error:false};static getDerivedStateFromError(){return {error:true}} render(){return this.state.error?<div className=\"chart-loading\">Не удалось загрузить график. <button className=\"text-button\" onClick={()=>window.location.reload()}>Попробовать ещё раз</button></div>:this.props.children}}
export function VisualizationWidget({mode,onModeChange,data,periodLabel,refreshing,onExport,onRefresh}:VisualizationWidgetProps) {
