  <div className=\"metrics\">{(monitoring?[{title:'Среднее время ответа',value:'94',unit:'мс',change:'−12,8%',icon:'clock' as IconName,spark:[23,17,24,19,14,18,12,16,10,15,8,11]},{title:'Запросов за час',value:'128 492',unit:'',change:'+16,2%',icon:'activity' as IconName,spark:[8,13,10,20,15,22,16,25,21,29,24,32]},{title:'Доступность',value:'99,98',unit:'%',change:'+0,02%',icon:'target' as IconName,spark:[22,24,23,24,25,25,26,26,26,27,27,28]},{title:'Ошибки',value:'0,02',unit:'%',change:'−0,08%',icon:'layers' as IconName,spark:[30,26,29,21,23,19,22,15,18,12,14,9]}]:[{title:'Общая выручка',value:period==='Последние 7 дней'?'642 800':period==='Последние 14 дней'?'1 204 200':'2 486 500',unit:'₽',change:'+14,2%',icon:'wallet' as IconName,spark:[9,14,11,15,12,22,19,23,19,27,24,32]},{title:'Заказы',value:period==='Последние 7 дней'?'642':'2 486',unit:'',change:'+8,6%',icon:'cart' as IconName,spark:[11,15,13,19,16,22,18,25,23,28,25,31]},{title:'Средний чек',value:'1 000',unit:'₽',change:'+5,2%',icon:'users' as IconName,spark:[15,18,16,21,18,23,20,25,22,26,24,30]},{title:'Конверсия',value:'3,24',unit:'%',change:'+0,4%',icon:'target' as IconName,spark:[10,13,12,18,15,22,19,24,21,27,25,32]}]).map((m,i)=><article className=\"metric-card\" key={m.title}><div className=\"metric-label\">{m.title}<span className=\"metric-icon\"><Icon name={m.icon} size={17}/></span></div><div className=\"metric-value\">{m.value}<span>{m.unit}</span></div><div className=\"metric-bottom\"><span className=\"metric-change\"><svg viewBox=\"0 0 12 12\" width=\"11\" height=\"11\" fill=\"none\"><path d=\"m2 8 7-5M4 3h5v5\" stroke=\"currentColor\" strokeWidth=\"1.4\" strokeLinecap=\"round\"/></svg>{m.change}</span><span>к прошлому периоду</span><svg className=\"sparkline\" viewBox=\"0 0 88 35\"><defs><linearGradient id={"'`spark-${i}`} x1="0" x2="0" y1="0" y2="1"><stop stopColor="#a989e5" stopOpacity=".14"/><stop offset="1" stopColor="#a989e5" stopOpacity="0"/></linearGradient></defs><path d={`M0 35 ${m.spark.map((v,j)=>`L${j*8} ${36-v}`).join('"' ')} L88 35Z"'`} fill={`url(#spark-${i})`}/><polyline points={m.spark.map((v,j)=>`${j*8},${36-v}`).join('"' ')} fill=\"none\" stroke=\"#a988de\" strokeWidth=\"1.6\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg></div></article>)}</div>
