}</strong><p>{s.kind} · {s.detail}</p></div><span className=\"source-status\"><span className=\"live-dot\"/>Подключён</span><button className=\"button small\" onClick={refresh}><Icon name=\"refresh\" size={15}/>Синхронизировать</button></div>)}</section>:page==='События'?<section className=\"panel all-events\"><div className=\"panel-heading\"><h2>Лента активности</h2><select value={eventFilter} onChange={e=>setEventFilter(e.target.value)}><option>Все события</option><option>Продажи</option><option>Синхронизация</option><option>Источники</option></select></div>{initialEvents.filter(e=>eventFilter==='Все события'||(eventFilter==='Продажи'&&e.type==='sale')||(eventFilter==='Синхронизация'&&e.type==='sync')||(eventFilter==='Источники'&&e.type==='source')).map(e=><div className=\"event\" key={e.title}><span className={"'`event-icon ${e.color}`}><Icon name={e.icon} size={20}/></span><div><strong>{e.title}</strong><p>{e.description}</p></div><time>{e.time}</time></div>)}</section>:<section className="panel settings-panel"><h2>Рабочее пространство</h2><label>Название проекта<input value={workspaceName} onChange={e=>setWorkspaceName(e.target.value)} placeholder="Название проекта"/></label><div className="setting-row"><div><strong>Уведомления о событиях</strong><p>Получайте уведомления о важных изменениях в данных</p></div><button className={`toggle ${notify?'"'on':''}"'`} role="switch" aria-checked={notify} aria-label="Уведомления о событиях" onClick={()=>setNotify(!notify)}><i/></button></div><button className="primary-button" onClick={()=>{if(!workspaceName.trim())return;setSavedName(workspaceName);setToast('"'Настройки сохранены')}}>Сохранить изменения</button></section>}
