 await expect(page.locator('.uplot canvas')).toBeVisible();
 await expect(page.getByRole('heading',{name:'Мониторинг в реальном времени'})).toBeVisible();
 expect(requests.some(r=>/MonitoringEngine.*\\.js/.test(r))).toBeTruthy();
 await page.getByRole('button',{name:'Приостановить'}).click();
 await expect(page.getByRole('button',{name:'Продолжить'})).toBeVisible();
 await page.getByRole('button',{name:'5 мин',exact:true}).click();
 await page.getByRole('tab',{name:'Продажи',exact:true}).click();
 await expect(page.locator('.recharts-surface').first()).toBeVisible();
 await expect(page.getByRole('button',{name:'День',exact:true})).toHaveClass('active');
 expect(errors).toEqual([]);
 await page.screenshot({path:'/tmp/pulse-desktop.png',fullPage:true});
});

test('period, legend visibility and CSV export are functional',async({page})=>{
 await page.goto('/');
 await page.getByRole('button',{name:'1 — 30 июня 2026'}).click();
 await page.getByRole('button',{name:'Последние 7 дней',exact:true}).click();
 await expect(page.locator('.engine-label')).toContainText('7 точек');
 await page.getByRole('button',{name:'Текущий период',exact:true}).click();
 await expect(page.locator('.recharts-area')).toHaveCount(0);
 await page.getByRole('button',{name:'Текущий период',exact:true}).click();
 await expect(page.locator('.recharts-area')).toHaveCount(1);
 const pendingDownload=page.waitForEvent('download');
 await page.getByRole('button',{name:'Экспорт',exact:true}).click();
 const download=await pendingDownload;expect(download.suggestedFilename()).toBe('pulse-sales-2026.csv');
 const stream=await download.createReadStream();const chunks:Buffer[]=[];for await(const chunk of stream"'!)chunks.push(chunk);
 const contents=Buffer.concat(chunks).toString('"'utf8');expect(contents).toContain('Выручка;Предыдущий период');expect(contents.trim().split('\\n')).toHaveLength(8);
});

